"""API contract tests against the generated demo dataset."""
from __future__ import annotations

import pytest
from fastapi.testclient import TestClient

from app.main import app

client = TestClient(app)


@pytest.fixture(scope="module", autouse=True)
def _demo_data():
    # Uses data/demo generated by `python -m app.services.data.generate_demo`
    from app.services.data.generate_demo import generate
    from app.core.config import settings

    generate(settings.data_dir)
    from app.services.data import repo
    from app.services.detection import pipeline, views

    repo.get_repo.cache_clear()
    pipeline.clear_cache()
    views.series_for.cache_clear()
    yield


def test_health():
    body = client.get("/healthz").json()
    assert body["status"] == "ok" and body["version"]


def test_meta_flags_demo_data():
    j = client.get("/api/meta").json()
    assert j["is_demo"] is True and "DEMO" in j["data_source"]
    assert "not predictions of failure" in j["disclaimer"]


def test_region_summary_rolls_up_children():
    j = client.get("/api/regions/IN/summary").json()
    assert j["by_tier"]["CRITICAL"] == 3
    assert j["data_degraded_sites"] == 1
    assert j["act_list"][0]["tier"] == "CRITICAL"
    # act list is ranked by RPI
    rpis = [s["rpi"] for s in j["act_list"]]
    assert rpis == sorted(rpis, reverse=True)


def test_unknown_region_404():
    assert client.get("/api/regions/NOPE/summary").status_code == 404


def test_sites_excludes_stable_by_default_and_filters():
    j = client.get("/api/sites").json()
    assert all(s["tier"] != "STABLE" for s in j["sites"])
    j2 = client.get("/api/sites?tier=CRITICAL").json()
    assert j2["count"] == 3


def test_site_detail_has_outlook_assumptions_and_no_failure_date():
    j = client.get("/api/sites/NH58-DEMO-010").json()
    assert j["tier"] == "CRITICAL"
    assert len(j["outlook"]["assumptions"]) >= 3
    assert "failure_date" not in j["outlook"]
    assert j["rain"]["source"] == "DEMO-SYNTHETIC"
    assert j["data_source"] == "DEMO-SYNTHETIC"


def test_timeseries_has_projection_and_threshold():
    j = client.get("/api/sites/NH58-DEMO-010/timeseries").json()
    assert len(j["dates"]) == len(j["disp_mm"]) > 30
    assert j["projection"]["constant_mm"] and j["projection"]["threshold_level_mm"] is not None


def test_degraded_site_has_no_projection():
    j = client.get("/api/sites/NH58-DEMO-016/timeseries").json()
    assert j["projection"] is None


def test_json_has_no_nan(  ):
    # NaN would make Starlette raise; every site must serialise
    for s in client.get("/api/sites?include_stable=true&limit=1000").json()["sites"][:40]:
        assert client.get(f"/api/sites/{s['site_id']}").status_code == 200


def test_points_viewport_is_capped():
    j = client.get("/api/points?bbox=79.0,30.0,80.0,31.0&limit=50").json()
    assert j["count"] <= 50 and j["truncated"] is True


def test_bad_bbox_400():
    assert client.get("/api/points?bbox=a,b").status_code == 400


def test_corridors_carry_worst_tier():
    j = client.get("/api/corridors").json()
    nh = next(f for f in j["features"] if f["properties"]["asset_id"] == "NH58-DEMO")
    assert nh["properties"]["worst_tier"] == "CRITICAL"
